using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using XNode;using Memories.Gameplay.Reactions;using Memories.Gameplay.Interaction;using Memories.Gameplay.Story;using Memories.Gameplay.Memories;
[InitializeOnLoad] public static class DockStorySetup {
const string R="Assets/_Project/Configs/Reactions/Park/", M="Assets/_Project/Configs/Memories/Park/ParkBoatMemory.asset", A="Assets/_Project/Art/Memories/Park/ParkBoatMemory/";
static DockStorySetup(){EditorApplication.delayCall+=Run;}
static void Set(UnityEngine.Object o,string name,object value){var so=new SerializedObject(o);var p=so.FindProperty(name);if(p==null)throw new Exception(o.name+" missing "+name);if(value is string s)p.stringValue=s;else if(value is bool b)p.boolValue=b;else if(value is int i)p.intValue=i;else if(value is float f)p.floatValue=f;else p.objectReferenceValue=value as UnityEngine.Object;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(o);}
static T Asset<T>(string path) where T:ScriptableObject{if(AssetDatabase.LoadAssetAtPath<T>(path))throw new Exception("Already exists "+path);Directory.CreateDirectory(Path.GetDirectoryName(path));var o=ScriptableObject.CreateInstance<T>();o.name=Path.GetFileNameWithoutExtension(path);AssetDatabase.CreateAsset(o,path);return o;}
static T Node<T>(NodeGraph g) where T:Node{var n=g.AddNode<T>();AssetDatabase.AddObjectToAsset(n,g);n.position=new Vector2((g.nodes.Count-1)*350,0);return n;}
static void Link(Node a,Node b,string output="next"){a.GetOutputPort(output).Connect(b.GetInputPort("previous"));EditorUtility.SetDirty(a);EditorUtility.SetDirty(b);}
static ReactionNode Action(ReactionGraph g,ReactionKind kind,string key=""){var n=Node<ReactionNode>(g);Set(n,"kind",(int)kind);Set(n,"objectKey",key);return n;}
static void Keys(ReactionGraph g,params string[] keys){var so=new SerializedObject(g);var p=so.FindProperty("objectKeys");foreach(var key in keys)if(!g.ObjectKeys.Contains(key)){int i=p.arraySize;p.InsertArrayElementAtIndex(i);p.GetArrayElementAtIndex(i).stringValue=key;}so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(g);}
static void Bind(ReactionInteractable i,string key,GameObject go){var so=new SerializedObject(i);var p=so.FindProperty("objectBindings");int ix=-1;for(int a=0;a<p.arraySize;a++)if(p.GetArrayElementAtIndex(a).FindPropertyRelative("key").stringValue==key)ix=a;if(ix<0){ix=p.arraySize;p.InsertArrayElementAtIndex(ix);}p.GetArrayElementAtIndex(ix).FindPropertyRelative("key").stringValue=key;p.GetArrayElementAtIndex(ix).FindPropertyRelative("target").objectReferenceValue=go;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(i);}
