static void Track(GameObject go,string id){var c=go.GetComponent<ObjectStateTracker>()??go.AddComponent<ObjectStateTracker>();Set(c,"persistentId",id);}
static void SaveGraph(NodeGraph g){EditorUtility.SetDirty(g);foreach(var n in g.nodes)EditorUtility.SetDirty(n);AssetDatabase.SaveAssetIfDirty(g);}
static void Run(){if(File.Exists("Temp/DockStorySetup.txt")||EditorApplication.isPlayingOrWillChangePlaymode)return;if(!File.Exists(A+"ParkBoatMemory-07.png"))return;try{var sc=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(sc.name!="Park")return;var all=sc.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Transform>(true)).ToArray();var lily=all.Single(x=>x.name=="Лили — на причале").gameObject;var boat=all.Single(x=>x.name=="Лодка 2 — вёсельная").gameObject;var cafeBank=AssetDatabase.LoadAssetAtPath<CustomVariableBank>("Assets/_Project/Configs/CustomVariables/ParkCafe.asset");var bank=Asset<CustomVariableBank>("Assets/_Project/Configs/CustomVariables/ParkDock.asset");var bs=new SerializedObject(bank);var vars=bs.FindProperty("variables");vars.arraySize=1;var v=vars.GetArrayElementAtIndex(0);v.FindPropertyRelative("id").stringValue="lily_spoken";v.FindPropertyRelative("name").stringValue="Лили предложила покататься на лодке";v.FindPropertyRelative("initialValue").boolValue=false;v.FindPropertyRelative("type").intValue=0;bs.ApplyModifiedPropertiesWithoutUndo();Set(bank,"bankId",AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(bank)));AssetDatabase.SaveAssetIfDirty(bank);
var story=Asset<StoryTextGraph>("Assets/_Project/Configs/StoryTexts/Park/Dock_Lily.asset");var ts=Node<StoryTextStartNode>(story);var tx=Node<StoryTextNode>(story);Set(tx,"text","Я предложил покататься на лодках. Колено болело. Но я искал способ... как сделать все лучше.");Set(tx,"duration",8f);var te=Node<StoryTextEndNode>(story);Link(ts,tx);Link(tx,te);SaveGraph(story);
var mem=Asset<MemoryGraph>(M);Set(mem,"displayTitle","Разговор на озере");Node last=Node<MemoryStartNode>(mem);string[] lines={"Здесь красивое место.","Да. Ты о чем-то хотела поговорить?","Знаешь, Алекс. Твоя травма. После неё ты стал... другим. Ты замкнулся в себе. И стал раздражительным. Как будто, совсем другой человек. Которого я не знаю.","Эй! Я лежал на койке бог знает сколько времени. Мне сказали, что я больше не смогу играть. Знаешь... Это сложно. Но я никогда не срывал это на тебе.","Может быть, тебе казалось, что ты не срывал.","Но... скажи, где я повел себя неправильно?","От этого копания в мелочах не будет лучше ни мне ни тебе. Ты просто... изменился."};float[] times={4,5,13,13,6,6,8};for(int i=0;i<7;i++){string ip=A+"ParkBoatMemory-"+(i+1).ToString("00")+".png";AssetDatabase.ImportAsset(ip,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(ip);importer.textureType=TextureImporterType.Default;importer.maxTextureSize=2048;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();var n=Node<MemoryFrameNode>(mem);Set(n,"image",AssetDatabase.LoadAssetAtPath<Texture2D>(ip));Set(n,"text",lines[i]);Set(n,"displayDuration",times[i]);Set(n,"transition",(int)MemoryFrameTransition.CrossFade);Set(n,"transitionDuration",.4f);Link(last,n);last=n;}Link(last,Node<MemoryEndNode>(mem));SaveGraph(mem);
var lg=Asset<ReactionGraph>(R+"Dock_Lily.asset");Keys(lg,"Лили на причале","Лодка");var start=Node<ReactionStartNode>(lg);Set(start,"runOnce",false);var end=Node<ReactionEndNode>(lg);var arrived=Condition(lg,cafeBank,"completed");var talked=Condition(lg,bank,"lily_spoken");var text=Action(lg,ReactionKind.StoryText);Set(text,"textGraph",story);var flag=Action(lg,ReactionKind.SetCustomVariable);Set(flag,"variableBank",bank);Set(flag,"variableId","lily_spoken");var disable=Action(lg,ReactionKind.ObjectInteractivity,"Лили на причале");Set(disable,"interactionEnabled",false);var enable=Action(lg,ReactionKind.ObjectInteractivity,"Лодка");Set(enable,"interactionEnabled",true);Link(start,arrived);Link(arrived,talked,"ifPresent");Link(arrived,end,"ifAbsent");Link(talked,end,"ifPresent");Link(talked,text,"ifAbsent");Link(text,flag);Link(flag,disable);Link(disable,enable);Link(enable,end);SaveGraph(lg);
var bg=Asset<ReactionGraph>(R+"Dock_Boat.asset");var bstart=Node<ReactionStartNode>(bg);Set(bstart,"runOnce",false);var bend=Node<ReactionEndNode>(bg);var bc=Condition(bg,bank,"lily_spoken");var ba=Condition(bg,cafeBank,"completed");var play=Action(bg,ReactionKind.Memory);Set(play,"memoryGraph",mem);Set(play,"memoryId","park-boat-conversation");Link(bstart,ba);Link(ba,bc,"ifPresent");Link(ba,bend,"ifAbsent");Link(bc,play,"ifPresent");Link(bc,bend,"ifAbsent");Link(play,bend);SaveGraph(bg);
var li=lily.GetComponent<ReactionInteractable>()??lily.AddComponent<ReactionInteractable>();li.Configure(lg,"Лили");Set(li,"initiallyVisible",false);Set(li,"initiallyInteractable",false);var bi=boat.GetComponent<ReactionInteractable>()??boat.AddComponent<ReactionInteractable>();bi.Configure(bg,"Лодка");Set(bi,"initiallyVisible",true);Set(bi,"initiallyInteractable",false);Bind(li,"Лили на причале",lily);Bind(li,"Лодка",boat);Track(lily,"park.dock.lily");Track(boat,"park.dock.boat");if(!lily.GetComponentsInChildren<Collider>(true).Any()){var c=lily.AddComponent<CapsuleCollider>();c.center=new Vector3(0,.9f,0);c.height=1.8f;c.radius=.3f;}if(!boat.GetComponentsInChildren<Collider>(true).Any()){var c=boat.AddComponent<BoxCollider>();var rs=boat.GetComponentsInChildren<Renderer>(true);var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);c.center=boat.transform.InverseTransformPoint(bounds.center);var scale=boat.transform.lossyScale;c.size=new Vector3(1.2f/scale.x,.65f/scale.y,2.7f/scale.z);}lily.SetActive(false);
var finish=AssetDatabase.LoadAssetAtPath<ReactionGraph>(R+"Cafe_Finish.asset");Keys(finish,"Лили на причале");var lighting=finish.nodes.OfType<ReactionNode>().Single(x=>x.Kind==ReactionKind.ChangeLighting);var next=ReactionGraph.Next(lighting);lighting.GetOutputPort("next").Disconnect(next.GetInputPort("previous"));var ready=Action(finish,ReactionKind.ObjectInteractivity,"Лили на причале");Set(ready,"interactionEnabled",true);var reveal=Action(finish,ReactionKind.ObjectActivity,"Лили на причале");Set(reveal,"active",true);Set(reveal,"revealDuration",4f);Set(reveal,"revealDelay",0f);var dissolvers=all.SelectMany(x=>x.GetComponents<ParkCafeDissolveReaction>()).ToArray();var restore=dissolvers.Single(x=>new SerializedObject(x).FindProperty("restoresCafe").boolValue);var shader=new SerializedObject(restore).FindProperty("dissolveShader").objectReferenceValue;Set(reveal,"revealShader",shader);Link(lighting,ready);Link(ready,reveal);Link(reveal,next);SaveGraph(finish);
foreach(var i in all.SelectMany(x=>x.GetComponents<ReactionInteractable>())){var so=new SerializedObject(i);var graph=so.FindProperty("graph").objectReferenceValue as ReactionGraph;if(graph&&AssetDatabase.GetAssetPath(graph).StartsWith(R+"Cafe_"))Bind(i,"Лили на причале",lily);}Set(restore,"dockVariables",bank);Set(restore,"dockLily",li);Set(restore,"dockBoat",bi);
var catalog=AssetDatabase.LoadAssetAtPath<MemoryCatalog>("Assets/_Project/Resources/MemoriesComicCatalog.asset");catalog.entries=catalog.entries.Concat(new[]{new MemoryCatalog.Entry{key=AssetDatabase.AssetPathToGUID(M),graph=mem}}).ToArray();EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssetIfDirty(catalog);
var report=new StringBuilder();foreach(var g in new[]{lg,bg,finish}){bool valid=g.TryGetSequence(out _,out var err);report.AppendLine(g.name+" valid="+valid+" "+err);if(!valid)throw new Exception(report.ToString());}if(!mem.TryGetSequence(out var frames,out var me))throw new Exception(me);if(!story.TryGetSequence(out _,out var se))throw new Exception(se);report.AppendLine("Frames="+frames.Count+"; Lily initially hidden; boat initially disabled; Cafe_BuyOrder unchanged; reveal begins before awaited order dissolve.");EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("Temp/DockStorySetup.txt",report.ToString());}catch(Exception e){File.WriteAllText("Temp/DockStorySetup.txt",e.ToString());}}
